import { type CnOptions, cn as mergeClasses } from "tailwind-variants";

export function cn(...classes: CnOptions): string {
  return mergeClasses(...classes) ?? "";
}

import { tv, type VariantProps } from "tailwind-variants";

export const buttonStyles = tv({
  base: "inline-flex shrink-0 cursor-default items-center justify-center gap-2 whitespace-nowrap rounded-md font-medium tracking-[-0.01em] data-[disabled]:cursor-default data-[disabled]:opacity-50 data-[disabled]:shadow-none data-[focus-visible]:outline-2 data-[focus-visible]:outline-offset-3 data-[focus-visible]:outline-ring",
  variants: {
    variant: {
      default:
        "bg-primary text-primary-foreground shadow-[var(--shadow-card)] hover:bg-primary/90 data-[pressed]:bg-primary/90",
      secondary:
        "bg-secondary text-secondary-foreground hover:bg-border/70 data-[pressed]:bg-border/70",
      outline:
        "border border-border bg-card text-foreground shadow-[var(--shadow-card)] hover:bg-muted data-[pressed]:bg-muted",
      ghost:
        "text-foreground hover:bg-muted data-[pressed]:bg-muted aria-[pressed=true]:bg-accent aria-[pressed=true]:text-accent-foreground aria-[pressed=true]:hover:bg-accent",
      destructive:
        "bg-destructive text-background shadow-[var(--shadow-card)] hover:bg-destructive/90 data-[pressed]:bg-destructive/90",
    },
    size: {
      default: "h-11 px-5 text-sm",
      sm: "h-9 px-3.5 text-sm",
      lg: "h-12 px-6 text-sm",
      icon: "size-11 cursor-pointer p-0",
    },
  },
  defaultVariants: { variant: "default", size: "default" },
});

export const buttonLinkStyles = tv({
  extend: buttonStyles,
  base: "cursor-pointer",
});

export type ButtonVariant = NonNullable<
  VariantProps<typeof buttonStyles>["variant"]
>;
export type ButtonSize = NonNullable<VariantProps<typeof buttonStyles>["size"]>;

"use client";

import { type MotionProps, motion, useReducedMotion } from "motion/react";
import {
  Button as AriaButton,
  type ButtonProps as AriaButtonProps,
  composeRenderProps,
} from "react-aria-components";
import {
  type ButtonSize,
  type ButtonVariant,
  buttonStyles,
} from "./button-styles";

export interface ButtonProps
  extends Omit<
    AriaButtonProps,
    | "style"
    | "onAnimationStart"
    | "onAnimationEnd"
    | "onAnimationIteration"
    | "onHoverStart"
    | "onHoverEnd"
  > {
  ref?: React.Ref<HTMLButtonElement>;
  variant?: ButtonVariant;
  size?: ButtonSize;
  static?: boolean;
  layout?: MotionProps["layout"];
}

const MotionButton = motion.create(AriaButton);

export function Button({
  className,
  variant = "default",
  size = "default",
  static: isStatic = false,
  layout,
  ...props
}: ButtonProps) {
  const reduceMotion = useReducedMotion();
  return (
    <MotionButton
      data-slot="button"
      data-variant={variant}
      data-size={size}
      layout={reduceMotion ? false : layout}
      whileHover={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 1.015 }
      }
      whileTap={
        isStatic || reduceMotion || props.isDisabled
          ? undefined
          : { scale: 0.96 }
      }
      transition={{ type: "spring", stiffness: 500, damping: 36 }}
      className={composeRenderProps(className, (className) =>
        buttonStyles({ variant, size, className }),
      )}
      {...props}
    />
  );
}

"use client";

import { AnimatePresence, motion, useReducedMotion } from "motion/react";
import { type ReactNode, useEffect, useRef, useState } from "react";
import { composeRenderProps } from "react-aria-components";
import { Check, Copy, Warning } from "reicon-react";
import { cn } from "./utils";
import { Button, type ButtonProps } from "./button";

export type CopyButtonStatus = "idle" | "copied" | "failed";

export interface CopyButtonProps
  extends Omit<
    ButtonProps,
    "children" | "onPress" | "type" | "value" | "layout"
  > {
  value: string;
  children?: ReactNode | ((status: CopyButtonStatus) => ReactNode);
}

const feedbackEase = [0.23, 1, 0.32, 1] as const;

export function CopyButton({
  value,
  children,
  variant = "outline",
  size = "default",
  "aria-label": ariaLabel = "Copy",
  className,
  ...props
}: CopyButtonProps) {
  const [status, setStatus] = useState<CopyButtonStatus>("idle");
  const resetTimer = useRef<number | null>(null);
  const requestId = useRef(0);
  const reduceMotion = useReducedMotion();

  useEffect(
    () => () => {
      requestId.current++;
      if (resetTimer.current !== null) window.clearTimeout(resetTimer.current);
    },
    [],
  );

  async function copy() {
    if (resetTimer.current !== null) window.clearTimeout(resetTimer.current);
    const id = ++requestId.current;
    setStatus("idle");

    let result: CopyButtonStatus;
    try {
      await navigator.clipboard.writeText(value);
      result = "copied";
    } catch {
      result = "failed";
    }

    if (id !== requestId.current) return;
    setStatus(result);
    resetTimer.current = window.setTimeout(() => setStatus("idle"), 2000);
  }

  const content = typeof children === "function" ? children(status) : children;
  const defaultContent = (
    <>
      {status === "copied" ? (
        <Check size={16} />
      ) : status === "failed" ? (
        <Warning size={16} />
      ) : (
        <Copy size={16} />
      )}
      {size !== "icon" &&
        (status === "copied"
          ? "Copied"
          : status === "failed"
            ? "Retry"
            : "Copy")}
    </>
  );

  return (
    <>
      <Button
        {...props}
        type="button"
        data-slot="copy-button"
        data-status={status}
        variant={variant}
        size={size}
        layout
        className={composeRenderProps(className, (className) =>
          cn("relative", className),
        )}
        aria-label={ariaLabel}
        onPress={() => void copy()}
      >
        <AnimatePresence initial={false} mode="popLayout">
          <motion.span
            key={
              typeof children === "function" || children == null
                ? status
                : "static"
            }
            layout={reduceMotion ? false : "position"}
            aria-hidden="true"
            initial={reduceMotion ? false : { opacity: 0 }}
            animate={{ opacity: 1 }}
            exit={{ opacity: reduceMotion ? 1 : 0 }}
            transition={{
              duration: reduceMotion ? 0 : 0.16,
              ease: feedbackEase,
            }}
            className="inline-flex items-center justify-center gap-2 whitespace-nowrap"
          >
            {children == null ? defaultContent : content}
          </motion.span>
        </AnimatePresence>
      </Button>
      <output className="sr-only" aria-live="polite" aria-atomic="true">
        {status === "copied"
          ? "Copied to clipboard"
          : status === "failed"
            ? "Copy failed. Try again."
            : ""}
      </output>
    </>
  );
}
